class Box:
    def __init__(self, items):
        self.items = items
    def __deepcopy__(self, memo):
        print("  (custom __deepcopy__ called)")
        return Box(copy.deepcopy(self.items, memo))
    def __repr__(self):
        return f"Box({self.items})"

b = Box([1, 2, 3])
b2 = copy.deepcopy(b)
print(b, b2, b.items is b2.items)
